session_start(); require '../config/database.php'; require '../lib_phase8.php';
if(!isset($_SESSION['user']) || $_SESSION['user']['role']!=='teacher'){header('Location: ../login.php');exit;}
$u=$_SESSION['user'];$tid=teacherId($pdo,(int)$u['id']);
$q=$pdo->prepare('SELECT t.department FROM teachers t WHERE t.id=?');$q->execute([$tid]);$teacher=$q->fetch()?:['department'=>''];
$q=$pdo->prepare("SELECT ta.id assignment_id,ta.term,ta.academic_year,ta.section_id,s.*,p.name program_name,p.level,p.specialization,sec.name section_name FROM teacher_assignments ta JOIN subjects s ON s.id=ta.subject_id JOIN programs p ON p.id=ta.program_id LEFT JOIN sections sec ON sec.id=ta.section_id WHERE ta.teacher_id=? AND ta.active=1 ORDER BY FIELD(p.level,'HSSC','BS','ADP'),p.name,ta.term,s.name,sec.name");$q->execute([$tid]);$subjects=$q->fetchAll();
$pageTitle='Teacher Dashboard'; require '../includes/header.php';?>
<div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h2 class="fw-bold mb-1">Teacher Dashboard</h2><p class="text-muted mb-0">Welcome, <?=htmlspecialchars($u['name'])?></p></div><a class="btn btn-outline-danger" href="../logout.php">Logout</a></div>
