<div class="card shadow-sm border-0"><div class="card-body"><h5 class="fw-bold">My Assigned Subjects</h5><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Program</th><th>Subject</th><th>Code</th><th>Year / Semester</th><th>Section</th><th>CH</th><th>Action</th></tr></thead><tbody><?php foreach($subjects as $s):?><tr><td><?=htmlspecialchars($s['level'].' — '.$s['program_name'])?></td><td><?=htmlspecialchars($s['name'])?></td><td><?=htmlspecialchars($s['code'])?></td><td><?=htmlspecialchars($s['term'])?></td><td><?=htmlspecialchars($s['section_name']?:'All Sections')?></td><td><?=htmlspecialchars($s['credit_hours'])?></td><td><a class="btn btn-sm btn-primary" href="attendance.php?assignment_id=<?=$s['assignment_id']?>">Attendance</a> <a class="btn btn-sm btn-outline-primary" href="marks.php?assignment_id=<?=$s['assignment_id']?>">Marks</a></td></tr><?php endforeach;if(!$subjects):?><tr><td colspan="7" class="text-muted">No class/subject assignments. Ask the administrator to assign your classes and subjects.</td></tr><?php endif;?></tbody></table></div></div></div></div><?php require '../includes/footer.php';?>
